begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
-- FIXTURE_BEGIN: owner-only synthetic source observations and reviewed mapping.
insert into auth.users(id,email,raw_user_meta_data) values('db560000-0000-4000-8000-000000000001','clinical-import-admin@example.test','{}'),('db560000-0000-4000-8000-000000000002','clinical-import-other@example.test','{}');
insert into user_roles(user_id,role) values('db560000-0000-4000-8000-000000000001','ADMIN'),('db560000-0000-4000-8000-000000000002','ADMIN');
create temp table fx(k text primary key,id uuid);create temp table data(k text primary key,v jsonb);grant all on fx,data to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db560000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Clinical','Import','+13035550199','clinical-import@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Scoped dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select k,gen_random_uuid() from unnest(array['mapping','mapping2','snapshot','snapshot2','legacy','terminal','run','history','other-run']) k;
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) select id,'https://api.trial.ezyvet.com','prescriptionitem-test-site','animal',case when k='snapshot' then '77' else '88' end,jsonb_build_object('id',case when k='snapshot' then 77 else 88 end),k,'db560000-0000-4000-8000-000000000001' from fx where k in ('snapshot','snapshot2');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by)
select id,gen_random_uuid(),k,'https://api.trial.ezyvet.com','prescriptionitem-test-site','animal',case when k='mapping' then '77' else '88' end,(select id from fx where k=case when m.k='mapping' then 'snapshot' else 'snapshot2' end),1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','Synthetic approved mapping','db560000-0000-4000-8000-000000000001' from fx m where k in ('mapping','mapping2');
insert into fx values('prescription-run',gen_random_uuid());
insert into data select 'prescription-run',claim_ezyvet_prescription_import((select id from fx where k='prescription-run'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescription','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select id from fx where k='prescription-run'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='prescription-run'),1,true,'[{"external_id":"101","payload":{"id":101,"animal_id":77,"instructions":"Source prescriptionation"}},{"external_id":"102","payload":{"id":102,"animal_id":77}}]');
insert into data select 'prescription',list_ezyvet_prescription_candidates((select id from fx where k='mapping'),'prescription')->'candidates'->0;
-- Choose external prescription 101 independent of creation-order ties.
update data set v=(select c from jsonb_array_elements(list_ezyvet_prescription_candidates((select id from fx where k='mapping'),'prescription')->'candidates') c where c->>'external_id'='101') where k='prescription';
insert into data values('items','[{"external_id":"501","payload":{"id":501,"prescription_id":101,"product_id":null,"date_start":null,"remaining":"unknown","qty":"outside units","serial_number":"outside author","instructions":"<script>outside prose</script>"}}]');
insert into data select 'legacy',to_jsonb(claim_ezyvet_import_core((select id from fx where k='legacy'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescriptionitem','https://api.trial.ezyvet.com'));
select stage_ezyvet_import_page_core((select id from fx where k='legacy'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='legacy'),1,false,(select v from data where k='items'));
update ezyvet_import_runs set retry_after=null,lease_until=null;
insert into data select 'terminal',to_jsonb(claim_ezyvet_import_core((select id from fx where k='terminal'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescriptionitem','https://api.trial.ezyvet.com'));
select stage_ezyvet_import_page_core((select id from fx where k='terminal'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='terminal'),1,true,'[]');
update ezyvet_import_runs set retry_after=null,lease_until=null;
reset role;
insert into data select 'review-run',claim_ezyvet_prescriptionitem_import((select id from fx where k='run'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','prescriptionitem','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),(select (v->>'id')::uuid from data where k='prescription'),(select v->>'payload_hash' from data where k='prescription'),(select (v->>'observed_head_version')::integer from data where k='prescription'));
select stage_ezyvet_import_page((select id from fx where k='run'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='review-run'),1,true,(select v from data where k='items'));
insert into data select 'context',ezyvet_prescription_source_context((select id from fx where k='pet'),(select id from fx where k='run'));

insert into fx values('product',gen_random_uuid());
insert into catalog_products(id,name,kind,unit,unit_price_cents,created_by) select id,'Synthetic medication','medication','tablet',1000,'db560000-0000-4000-8000-000000000001' from fx where k='product';
insert into data select 'review',jsonb_build_object('reason','Historical interpretation only','outside_author',null,'prescribed_on',null,'prescription_date_status','uninterpreted','status','unknown','completeness','partial','partial_reason','Parent source list not supplied','replaces_id',null,'expected_predecessor_hash',null,'items',jsonb_build_array(jsonb_build_object('snapshot_id',v#>'{items,0,snapshot_id}','start_on',null,'start_date_status','unknown','product_id',(select id from fx where k='product'),'product_version',1,'note','No dose or refill inferred'))) from data where k='context';

insert into user_roles(user_id,role) values('db560000-0000-4000-8000-000000000001','DVM'),('db560000-0000-4000-8000-000000000002','DVM');
insert into fx select k,gen_random_uuid() from unnest(array['approval','duplicate','correction','competing','stale','abandon']) k;
insert into data select 'payload',jsonb_build_object('item_run_id',(select id from fx where k='run'),'patient_version',(select version from pets where id=(select id from fx where k='pet')),'interpretation',v) from data where k='review';
insert into data values('side-effects',jsonb_build_object('treatments',(select count(*) from patient_treatments),'invoices',(select count(*) from billing_invoices),'stock',(select count(*) from inventory_movements),'certificates',(select count(*) from vaccine_certificates),'reminders',(select count(*) from care_reminder_jobs),'outbox',(select count(*) from communication_outbox)));

reset role;
insert into fx select k,gen_random_uuid() from unnest(array['attachment-animal','attachment-consult','attachment-legacy','attachment-consult-source']) k;
insert into data select 'attachment-consult-source',claim_ezyvet_clinical_import((select id from fx where k='attachment-consult-source'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','consult','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select id from fx where k='attachment-consult-source'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-consult-source'),1,true,'[{"external_id":"201","payload":{"id":201,"animal_id":77}}]');
insert into data select 'attachment-parent',jsonb_build_object('id',s.id,'hash',s.payload_hash,'version',h.version) from ezyvet_import_snapshots s join ezyvet_identity_heads h on h.snapshot_id=s.id where s.resource='consult' and s.external_id='201';
select throws_ok($$select claim_ezyvet_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','attachment','https://api.trial.ezyvet.com')$$,'23514',null,'Generic attachment claim denied');
insert into data select 'attachment-legacy',to_jsonb(claim_ezyvet_import_core((select id from fx where k='attachment-legacy'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','attachment','https://api.trial.ezyvet.com'));
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-legacy'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-legacy'),1,true,'[]')$$,'22023','ATTACHMENT_RUN_REQUIRES_NEW_CONTEXT','Legacy core run cannot bypass scoped stage');
update ezyvet_import_runs set retry_after=null,lease_until=null;
select throws_ok($$select claim_ezyvet_attachment_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Contact',(select id from fx where k='snapshot'),'snapshot',1)$$,'23514',null,'Contact attachments cannot become patient records implicitly');
select throws_ok($$select claim_ezyvet_attachment_import((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Animal',(select id from fx where k='snapshot'),'snapshot',1)$$,'40001','SOURCE_ATTACHMENT_PARENT_STALE','Animal mapping without a current observation cannot authorize intake');
-- Explicit owner-only synthetic observation; the production adapter uses scoped/core stage receipts.
insert into ezyvet_identity_heads(source_origin,source_site_uid,resource,external_id,snapshot_id,version) select source_origin,source_site_uid,resource,external_id,id,1 from ezyvet_import_snapshots where id=(select id from fx where k='snapshot');
insert into data select 'attachment-animal',claim_ezyvet_attachment_import((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Animal',(select id from fx where k='snapshot'),'snapshot',1);
select is((select v#>>'{parent_context,parent_external_id}' from data where k='attachment-animal'),'77','Animal attachment parent derives from reviewed mapping');
insert into data values('attachment-items','[{"external_id":"701","payload":{"id":701,"record_type":"Animal","record_id":77,"file_id":"different-id","mime_type":"unsupported/example","file_download_url":"https://untrusted.example.test/file","name":"<script>original</script>"}}]');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-animal'),1,true,'[{"external_id":"701","payload":{"id":701,"record_type":"Animal","record_id":88}}]')$$,'23514',null,'Wrong patient metadata rejected');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000002',(select (v->>'lease_id')::uuid from data where k='attachment-animal'),1,true,(select v from data where k='attachment-items'))$$,'42501',null,'Other administrator cannot stage owned page');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-animal'),1,true,(select v||v from data where k='attachment-items'))$$,'23514',null,'Duplicate attachment identities reject whole page');
insert into data select 'attachment-staged',to_jsonb(stage_ezyvet_import_page((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-animal'),1,true,(select v from data where k='attachment-items')));
select is((select count(*)::integer from ezyvet_attachment_pages),1,'Exactly one durable page receipt');
select is((select count(*)::integer from ezyvet_attachment_page_observations),1,'Exact observed source revision retained');
select is((select payload->>'mime_type' from ezyvet_import_snapshots where resource='attachment' and external_id='701'),'unsupported/example','Unsupported file metadata retained for later discrepancy review');
select is((select payload->>'file_download_url' from ezyvet_import_snapshots where resource='attachment' and external_id='701'),'https://untrusted.example.test/file','Original URL remains evidence only');
update ezyvet_identity_heads set version=version+1 where resource='animal' and external_id='77';
select is(to_jsonb(stage_ezyvet_import_page((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001',null,1,true,(select v from data where k='attachment-items'))),(select v from data where k='attachment-staged'),'Exact committed page recovers before changed parent check');
select is(claim_ezyvet_attachment_import((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Animal',(select id from fx where k='snapshot'),'snapshot',1)->>'status','review_ready','Terminal claim recovers original context after source change');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001',null,1,false,(select v from data where k='attachment-items'))$$,'40001',null,'Changed completion flag cannot replay committed page');
select throws_ok($$select claim_ezyvet_attachment_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Animal',(select id from fx where k='snapshot'),'snapshot',1)$$,'40001','SOURCE_ATTACHMENT_PARENT_STALE','Fresh run rejects superseded animal revision');
update ezyvet_import_runs set retry_after=null,lease_until=null;
insert into data select 'attachment-consult',claim_ezyvet_attachment_import((select id from fx where k='attachment-consult'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Consult',(v->>'id')::uuid,v->>'hash',(v->>'version')::integer) from data where k='attachment-parent';
select is((select v#>>'{parent_context,parent_external_id}' from data where k='attachment-consult'),'201','Consult parent resolves from scoped same-patient evidence');
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-consult'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-consult'),1,true,(select v from data where k='attachment-items'))$$,'23514',null,'Animal page cannot enter consultation run');
select stage_ezyvet_import_page((select id from fx where k='attachment-consult'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-consult'),1,false,'[{"external_id":"702","payload":{"id":702,"record_type":"Consult","record_id":201}}]');
select is((select count(*)::integer from ezyvet_attachment_pages where run_id=(select id from fx where k='attachment-consult')),1,'Valid consultation metadata has its own durable page');
update ezyvet_import_runs set retry_after=null,lease_until=null;
update data set v=claim_ezyvet_attachment_import((select id from fx where k='attachment-consult'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Consult',(select (v->>'id')::uuid from data where k='attachment-parent'),(select v->>'hash' from data where k='attachment-parent'),(select (v->>'version')::integer from data where k='attachment-parent')) where k='attachment-consult';
update ezyvet_identity_heads set version=version+1 where resource='consult' and external_id='201';
select throws_ok($$select stage_ezyvet_import_page((select id from fx where k='attachment-consult'),'db560000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='attachment-consult'),2,true,'[{"external_id":"702","payload":{"id":702,"record_type":"Consult","record_id":201}}]')$$,'40001','SOURCE_CONSULT_STALE','Fresh page rejects changed consultation revision');
set local role authenticated;
select is(recover_ezyvet_attachment_run((select id from fx where k='attachment-consult'),(select id from fx where k='mapping'))#>>'{parent_context,parent_external_id}','201','Pending run remains discoverable after parent change');
select is(jsonb_array_length(list_ezyvet_attachment_runs((select id from fx where k='mapping'))->'runs'),2,'Owner discovery includes both scoped parent types');
select ok((list_ezyvet_attachment_runs((select id from fx where k='mapping'),null,null,1)->>'has_more')::boolean,'Run discovery uses bounded cursor pagination');
select ok(not (recover_ezyvet_attachment_run((select id from fx where k='attachment-animal'),(select id from fx where k='mapping')) ? 'lease_id'),'Recovery does not expose service lease');
select throws_ok($$select recover_ezyvet_attachment_run((select id from fx where k='attachment-animal'),(select id from fx where k='mapping2'))$$,'42501',null,'Wrong mapping recovery rejected');
select set_config('request.jwt.claims','{"sub":"db560000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select recover_ezyvet_attachment_run((select id from fx where k='attachment-animal'),(select id from fx where k='mapping'))$$,'42501',null,'Wrong actor recovery rejected');
reset role;
select ok(not has_table_privilege('authenticated','public.ezyvet_attachment_runs','select'),'Private run table denied to authenticated');
select ok(not has_table_privilege('service_role','public.ezyvet_attachment_pages','insert'),'Service role cannot insert forged receipt');
select ok(not has_function_privilege('service_role','public.ezyvet_attachment_parent_context(uuid,text,text,text,uuid,text,integer)','execute'),'Parent helper remains private');
select ok(not has_function_privilege('authenticated','public.claim_ezyvet_attachment_import(uuid,uuid,text,text,uuid,text,uuid,text,integer)','execute'),'Browser cannot forge service actor');
select is(jsonb_build_object('treatments',(select count(*) from patient_treatments),'invoices',(select count(*) from billing_invoices),'stock',(select count(*) from inventory_movements),'certificates',(select count(*) from vaccine_certificates),'reminders',(select count(*) from care_reminder_jobs),'outbox',(select count(*) from communication_outbox)),(select v from data where k='side-effects'),'Metadata intake creates no native clinical, stock, billing or delivery effects');
select throws_ok($$select claim_ezyvet_attachment_import(gen_random_uuid(),'db560000-0000-4000-8000-000000000001','other-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Animal',(select id from fx where k='snapshot'),'snapshot',2)$$,'42501',null,'Cross-site parent cannot authorize a run');
select throws_ok($$update ezyvet_attachment_pages set request_hash=repeat('a',64)$$,'23514',null,'Committed metadata receipts cannot be rewritten');
select throws_ok($$select claim_ezyvet_attachment_import((select id from fx where k='attachment-animal'),'db560000-0000-4000-8000-000000000001','prescriptionitem-test-site','https://api.trial.ezyvet.com',(select id from fx where k='mapping'),'Animal',(select id from fx where k='snapshot'),'snapshot',2)$$,'42501',null,'Same run cannot be retargeted to a newer parent revision');
select * from finish();rollback;
